from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from .api.routes import router
from .api.signals import router as signals_router
from .api.live import router as live_router
from .db import init_db

app=FastAPI(title='Qanas Data Engine',version='0.5.7')
@app.on_event('startup')
def startup(): init_db()
app.include_router(router,prefix='/api'); app.include_router(signals_router,prefix='/api'); app.include_router(live_router,prefix='/api')

HTML=r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>قنص</title><style>
:root{--bg:#05090d;--p:#081119;--l:#172631;--t:#f3f6f7;--m:#71828e;--g:#42d392;--a:#f2a94b;--gold:#d8b468;--c:#58bce8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font:13px Segoe UI,Tahoma,Arial}.wrap{padding:9px 11px}.top,.actions,.filters,.quick{display:flex;align-items:center;gap:7px}.top{height:46px;justify-content:space-between}.brand{display:flex;align-items:center;gap:8px}.logo{width:35px;height:35px;border:1px solid #755f36;border-radius:9px;display:grid;place-items:center;color:var(--gold);font-weight:900;font-size:18px}.brand b{font-size:19px}.btn,.f{border:1px solid var(--l);background:#09131a;color:var(--t);border-radius:8px;padding:7px 9px}.gold{background:#c9a75e;color:#080a0b;font-weight:800}.good,.live{color:var(--g);font-weight:800}.amber{color:var(--a);font-weight:800}.cyan{color:var(--c);font-weight:800}.refreshinfo{font-size:10px;color:var(--m);white-space:nowrap}.refreshinfo b{color:#b7c4cc;font-weight:700}.quick{border:1px solid var(--l);background:#071017;border-radius:9px;padding:6px 8px;overflow:auto;margin-bottom:6px}.qs{white-space:nowrap;padding:0 9px;border-left:1px solid var(--l)}.qs span{font-size:9px;color:var(--m)}.qs b{margin-right:5px}.bar{display:flex;gap:6px;align-items:center;position:sticky;top:0;z-index:30;background:#071017;border:1px solid var(--l);border-radius:9px;padding:6px;margin-bottom:6px}.search{flex:1;min-width:190px}.search input{width:100%;height:32px;background:#040a0e;border:1px solid #1a2c37;color:white;border-radius:7px;padding:0 9px}.filters{overflow:auto;white-space:nowrap}.f.active{background:#c9a75e;color:#080a0b;font-weight:800}.tablebox{border:1px solid var(--l);border-radius:8px;overflow:auto;max-height:calc(100vh - 108px)}table{width:100%;min-width:1450px;border-collapse:separate;border-spacing:0;font-variant-numeric:tabular-nums}th,td{padding:7px 8px;border-bottom:1px solid #12212b;text-align:right;white-space:nowrap;height:42px}th{font-size:9px;color:#748692;background:#081119;position:sticky;top:0;z-index:20}.tc{position:sticky;right:0;background:#071017;z-index:12}.ticker{font-size:14px;font-weight:900}.co{font-size:8px;color:var(--m);max-width:120px;overflow:hidden;text-overflow:ellipsis}.badge{display:inline-block;padding:4px 7px;border-radius:6px;font-weight:900;background:#292419;color:#e2bd70;border:1px solid #504329}.b100{background:#123026;color:#5be0a5;border-color:#285944}.b90{background:#322514;color:#ffc468;border-color:#624724}.miss{max-width:300px;overflow:hidden;text-overflow:ellipsis}.trophy{display:inline-flex;align-items:center;gap:5px;padding:4px 7px;border:1px solid #59491f;border-radius:7px;background:#211b0d;color:#ffd66b;font-weight:900}.mobile{display:none}.drawer{display:none;position:fixed;inset:0;background:#000b;z-index:60}.drawer.open{display:block}.sheet{position:absolute;left:0;top:0;height:100%;width:min(540px,96vw);background:#071017;padding:18px;overflow:auto}.close{float:left;background:#101b23;border:1px solid var(--l);color:white;border-radius:7px;font-size:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:12px}.mini{background:#0a141c;border:1px solid var(--l);border-radius:8px;padding:10px}.mini span{display:block;color:var(--m);font-size:9px;margin-bottom:4px}.fresh{display:inline-flex;align-items:center;gap:4px;font-size:8px;color:var(--m)}.fresh i{width:6px;height:6px;border-radius:50%;background:var(--g)}
@media(max-width:700px){body{font-size:12px;background:linear-gradient(180deg,#09100f 0,#05090d 32%,#030609 100%)}.wrap{padding:0 8px 82px}.top{height:auto;min-height:92px;margin:0 -8px 10px;padding:14px 12px 12px;background:linear-gradient(135deg,#11180f,#071117 60%,#0d120d);border-bottom:1px solid #2e3022;box-shadow:0 12px 35px #0008}.brand{align-self:flex-start}.logo{width:44px;height:44px;border:1px solid #8d7440;border-radius:14px;background:linear-gradient(145deg,#1e1a0f,#0b1011);font-size:23px;box-shadow:0 0 28px #d8b46820}.brand b{font-size:22px;letter-spacing:.5px}.brand b:after{content:'  ·  MOBILE TERMINAL';display:block;font-size:7px;letter-spacing:1.5px;color:#8e8468;margin-top:3px;direction:ltr}.actions{max-width:210px;gap:5px;flex-wrap:wrap;justify-content:flex-end}.actions #state{width:auto;order:1;font-size:9px;padding:4px 7px;border:1px solid #214936;border-radius:20px;background:#0b1d16}.actions .refreshinfo{order:2;width:100%;text-align:left;font-size:8px}.actions .refresh{order:3;display:inline-flex;background:#123126;border-color:#2d6c50;color:#69e7ae;font-weight:900;min-width:76px;justify-content:center;border-radius:10px}.actions #bb{order:4;min-width:100px;font-size:9px;border-radius:10px}.actions .refresh::before{content:'↻';font-size:15px;margin-left:5px}.actions .refresh{font-size:0}.actions .refresh::after{content:'تحديث LIVE';font-size:10px}.btn{padding:8px 9px}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;border:0;background:transparent;padding:0;margin:0 0 10px;overflow:visible}.qs{border:1px solid #172a32!important;border-radius:12px;background:linear-gradient(145deg,#0b161d,#070d11);padding:9px 4px!important;text-align:center;min-width:0}.qs span{display:block;font-size:7px;margin-bottom:4px}.qs b{display:block;margin:0;font-size:15px}.qs:nth-child(n+5){display:none}.bar{display:block;top:0;margin:0 -2px 10px;padding:8px;background:#071016f5;border-color:#20313a;border-radius:14px;backdrop-filter:blur(18px);box-shadow:0 12px 28px #0008}.search{width:100%;margin:0 0 8px}.search input{height:42px;border-radius:11px;padding:0 13px;background:#03090d;border-color:#20333d;font-size:12px}.filters{display:flex;gap:6px;padding:0 0 1px;overflow-x:auto;scrollbar-width:none}.filters::-webkit-scrollbar{display:none}.f{flex:0 0 auto;padding:9px 12px;font-size:10px;border-radius:10px;background:#0a141a}.f.active{background:linear-gradient(135deg,#d8b468,#a98443);border-color:#e1c47f;color:#090b0c;box-shadow:0 5px 18px #d8b46820}.tablebox{display:none}.mobile{display:block}.cards{display:grid;gap:11px;padding-bottom:25px}.card{position:relative;overflow:hidden;background:linear-gradient(155deg,#0d1921,#070d12 68%);border:1px solid #1d303a;border-radius:17px;padding:13px;box-shadow:0 10px 28px #0007}.card:after{content:'›';position:absolute;left:11px;top:50%;transform:translateY(-50%);color:#43535c;font-size:22px}.card:active{transform:scale(.992)}.card.readycard{border-color:#2e7253;background:linear-gradient(145deg,#0d2119,#081118 68%);box-shadow:0 10px 30px #0007,0 0 22px #42d3920c}.card.readycard:before{content:'🎯';position:absolute;left:12px;top:10px;font-size:14px}.launchcard{border-color:#7b6228;background:linear-gradient(145deg,#211a09,#0b0e10 70%);box-shadow:0 10px 32px #0009,0 0 25px #d8b4680c}.launchcard:after{display:none}.launchhero{display:flex;align-items:center;justify-content:space-between;margin:10px 0;padding:13px;border:1px solid #685426;border-radius:13px;background:linear-gradient(135deg,#211a08,#0e0e09)}.launchrank{font-size:32px}.launchpct{font-size:31px;font-weight:950;color:#ffd66b;line-height:1;text-shadow:0 0 20px #d8b46830}.launchsub{font-size:8px;color:#b3a47b;margin-top:4px}.cardtop{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:11px;padding-left:18px}.sym{font-size:23px;font-weight:950;letter-spacing:.6px}.co{font-size:8px;max-width:180px;margin-top:2px}.cprice{font-size:20px;margin-top:5px}.badge{padding:5px 9px;border-radius:20px}.metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin-top:4px;padding-left:15px}.metric{display:flex;align-items:center;justify-content:space-between;background:#050b0f;border:1px solid #142630;border-radius:10px;padding:9px 10px;text-align:right}.metric span{display:block;color:#71828e;font-size:8px;margin:0}.metric b{font-size:12px}.need{margin:9px 15px 0 0;border-top:1px solid #172631;padding-top:9px;color:#f2a94b;font-weight:700;line-height:1.55;font-size:10px}.readyline{height:5px;background:#17242d;border-radius:5px;margin:9px 15px 0 0;overflow:hidden}.readyline i{display:block;height:100%;background:linear-gradient(90deg,#42d392,#8cf2c4);box-shadow:0 0 10px #42d392}.fresh{margin:8px 15px 0 0;padding-top:7px;border-top:1px dashed #16242c;font-size:8px}.fresh i{box-shadow:0 0 9px var(--g)}.sheet{top:auto;bottom:0;height:min(88vh,760px);width:100%;padding:18px 15px 30px;border-radius:22px 22px 0 0;border-top:1px solid #33454d;box-shadow:0 -15px 50px #000c}.sheet:before{content:'';display:block;width:42px;height:4px;border-radius:4px;background:#33434b;margin:-7px auto 12px}.close{border-radius:50%;width:34px;height:34px}.grid{gap:7px}.mini{padding:11px;border-radius:11px;background:#09141b}}
</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="logo">ق</div><b>قنص</b></div><div class="actions"><span id="state" class="good">● متصل</span><span class="refreshinfo">آخر تحديث: <b id="refreshedAt">—</b></span><button class="btn refresh" onclick="load(true)">تحديث</button><button id="bb" class="btn gold" onclick="borrow()">تحديث Borrow</button></div></div><div class="quick"><div class="qs"><span>الأسهم</span><b id="total">—</b></div><div class="qs"><span>≤10K</span><b id="scarce">—</b></div><div class="qs"><span>قرب القاع</span><b id="near">—</b></div><div class="qs"><span>🎯 الأجهز</span><b id="ready">—</b></div><div class="qs"><span>آخر Borrow</span><b id="last">—</b></div></div><div class="bar"><div class="search"><input id="q" placeholder="ابحث بالسهم أو الشركة..." oninput="render()"></div><div class="filters"><button class="f active" onclick="sf('all',this)">الكل</button><button class="f" onclick="sf('ready',this)">🎯 الأجهز</button><button class="f" onclick="sf('launched',this)">🏆 انطلاقات +40%</button><button class="f" onclick="sf('scarce',this)">Available</button><button class="f" onclick="sf('near',this)">قرب القاع</button></div></div><div class="tablebox"><table><thead><tr><th class="tc">السهم</th><th>الجاهزية / الإنجاز</th><th>Available</th><th>CTB</th><th>Rebate</th><th>LIVE</th><th>القاع</th><th>عن القاع</th><th>القمة</th><th>النصف</th><th>الثبات</th><th>أعلى انطلاقة</th><th>وش باقي؟</th><th>التاريخ</th><th>التقسيم</th></tr></thead><tbody id="rows"></tbody></table></div><div class="mobile"><div id="cards" class="cards"></div></div></div><div id="drawer" class="drawer" onclick="if(event.target===this)closeD()"><div class="sheet"><button class="close" onclick="closeD()">×</button><div id="detail"></div></div></div><script>
let data=[],signals={},live={},filter='all';const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:2}),money=n=>n==null?'—':'$'+Number(n).toFixed(4),pct=n=>n==null?'—':Number(n).toFixed(2)+'%';function rank(x){return x.signal?.ready?100:Number(x.signal?.readiness_pct??x.ready_score??0)}function medal(i){return i===0?'🥇':i===1?'🥈':i===2?'🥉':'#'+(i+1)}function ago(v){if(!v)return'—';let d=new Date(v.endsWith&&v.endsWith('Z')?v:v+'Z'),m=Math.max(0,Math.floor((Date.now()-d)/60000));return m<1?'الآن':m<60?'قبل '+m+' د':m<1440?'قبل '+Math.floor(m/60)+' س':'قبل '+Math.floor(m/1440)+' ي'}function sf(f,e){filter=f;document.querySelectorAll('.f').forEach(x=>x.classList.remove('active'));e.classList.add('active');render()}function stampRefresh(){let n=new Date();refreshedAt.textContent=n.toLocaleString('ar-SA',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'})}async function load(manual=false){try{state.textContent=manual?'● جاري التحديث اليدوي':'● جاري التحديث';let[d,s,l]=await Promise.all([fetch('/api/hunt',{cache:'no-store'}).then(r=>r.json()),fetch('/api/signals',{cache:'no-store'}).then(r=>r.json()),fetch('/api/live-prices',{cache:'no-store'}).then(r=>r.json())]);signals=Object.fromEntries(s.map(x=>[x.symbol,x]));live=Object.fromEntries(l.map(x=>[x.symbol,x]));data=d.map(x=>({...x,signal:signals[x.symbol]||null,live:live[x.symbol]||null}));stampRefresh();state.textContent='● متصل';summary();render()}catch(e){state.textContent='● خطأ بالتحديث'}}function summary(){total.textContent=data.length;scarce.textContent=data.filter(x=>x.available!=null&&x.available<=10000).length;near.textContent=data.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10).length;ready.textContent=data.filter(x=>x.signal?.ready||x.signal?.near_ready).length;let d=data.map(x=>x.borrow_timestamp).filter(Boolean).sort().pop();last.textContent=d?new Date(d+'Z').toLocaleDateString('ar-SA'):'—'}function filtered(){let a=data,v=q.value.trim().toUpperCase();a=a.filter(x=>!v||x.symbol.includes(v)||(x.company||'').toUpperCase().includes(v));if(filter==='scarce')a=a.filter(x=>x.available!=null&&x.available<=10000);if(filter==='near')a=a.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10);if(filter==='ready')a=a.filter(x=>x.signal?.ready||x.signal?.near_ready);if(filter==='launched')a=a.filter(x=>x.signal?.launched);a.sort((a,b)=>filter==='launched'?(b.signal?.rise_pct||0)-(a.signal?.rise_pct||0):filter==='ready'?(rank(b)-rank(a)||((a.available??1e12)-(b.available??1e12))||((a.distance_from_low_pct??1e9)-(b.distance_from_low_pct??1e9))):(b.ready_score||0)-(a.ready_score||0));return a}function render(){let a=filtered();rows.innerHTML=a.map((x,i)=>row(x,i)).join('');cards.innerHTML=a.map((x,i)=>card(x,i)).join('')||'<div style="text-align:center;color:var(--m);padding:30px">لا توجد نتائج</div>'}function badge(x){let r=rank(x),s=x.signal,cl=r>=100?'b100':r>=90?'b90':'';return s?.ready||s?.near_ready?`<span class="badge ${cl}">${fmt(r)}%${s?.ready?' 🎯':''}</span>`:`<span>${fmt(x.ready_score)}%</span>`}function row(x,i=0){let s=x.signal,l=x.live?.live_price,p=l??x.current_price,m=s?.ready?'مكتمل ✓':s?.missing||'—';return `<tr onclick="openD('${x.symbol}')"><td class="tc"><b class="ticker">${x.symbol}</b><div class="co">${x.company||''}</div></td><td>${filter==='launched'?`<span class="trophy">${medal(i)} 🚀 ${pct(s?.rise_pct)}</span>`:badge(x)}</td><td class="${x.available<=10000?'good':''}">${fmt(x.available)}</td><td style="color:var(--gold)">${pct(x.ctb)}</td><td class="cyan">${pct(x.rebate_rate)}</td><td class="${l!=null?'live':''}">${money(p)}</td><td>${money(x.post_split_low)}</td><td>${pct(x.distance_from_low_pct)}</td><td>${money(x.post_split_high)}</td><td>${money(x.half_level)} ${x.half_level_reached?'✓':''}</td><td>${fmt(x.stability_sessions)}/4</td><td class="good">${s?.rise_pct!=null?pct(s.rise_pct):'—'}</td><td class="miss amber">${m}</td><td>${s?.launched_at||s?.ready_at?new Date(s.launched_at||s.ready_at).toLocaleDateString('ar-SA'):'—'}</td><td>${x.ratio}</td></tr>`}function card(x,i=0){let s=x.signal,l=x.live?.live_price,p=l??x.current_price,r=rank(x),m=s?.ready?'مكتمل ✓':s?.missing||'—',cls=(s?.ready||s?.near_ready)?' readycard':'';if(filter==='launched')return `<div class="card launchcard" onclick="openD('${x.symbol}')"><div class="cardtop"><div><div class="sym">${x.symbol}</div><div class="co">${x.company||''}</div></div><div class="launchrank">${medal(i)}</div></div><div class="launchhero"><div><div class="launchsub">أعلى انطلاقة · آخر 10 جلسات</div><div class="launchpct">🚀 ${pct(s?.rise_pct)}</div></div><div style="text-align:left"><div class="launchsub">أعلى سعر مسجل</div><b style="font-size:16px;color:#ffd66b">${money(s?.max_price_after_ready)}</b></div></div><div class="metrics"><div class="metric"><span>الترتيب</span><b>${medal(i)}</b></div><div class="metric"><span>LIVE</span><b class="${l!=null?'live':''}">${money(p)}</b></div><div class="metric"><span>تاريخ الانطلاق</span><b>${s?.launched_at?new Date(s.launched_at).toLocaleDateString('ar-SA'):'—'}</b></div><div class="metric"><span>Available</span><b>${fmt(x.available)}</b></div></div><div class="fresh"><i></i> LIVE ${x.live?.live_timestamp?ago(x.live.live_timestamp):'—'} · Borrow ${ago(x.borrow_timestamp)}</div></div>`;return `<div class="card${cls}" onclick="openD('${x.symbol}')"><div class="cardtop"><div><div class="sym">${x.symbol}</div><div class="co">${x.company||''}</div></div><div style="text-align:left">${badge(x)}<div class="cprice ${l!=null?'live':''}">${money(p)}</div></div></div><div class="metrics"><div class="metric"><span>Available</span><b class="${x.available<=10000?'good':''}">${fmt(x.available)}</b></div><div class="metric"><span>عن القاع</span><b>${pct(x.distance_from_low_pct)}</b></div><div class="metric"><span>الثبات</span><b>${fmt(x.stability_sessions)}/4</b></div><div class="metric"><span>CTB</span><b>${pct(x.ctb)}</b></div></div>${s?.ready||s?.near_ready?`<div class="readyline"><i style="width:${Math.min(100,r)}%"></i></div>`:''}<div class="need">${m}</div><div class="fresh"><i></i> LIVE ${x.live?.live_timestamp?ago(x.live.live_timestamp):'—'} · Borrow ${ago(x.borrow_timestamp)}</div></div>`}async function openD(symbol){drawer.classList.add('open');detail.innerHTML='جاري التحميل...';try{let[s,h]=await Promise.all([fetch('/api/stock/'+symbol).then(r=>r.json()),fetch('/api/borrow/'+symbol+'/history?limit=8').then(r=>r.json())]),g=signals[symbol],l=live[symbol];detail.innerHTML=`<h2 style="font-size:30px;margin:3px 0">${s.symbol}</h2><div style="color:var(--m)">${s.company||''}</div>${g?.launched?`<div class="mini" style="margin-top:10px;border-color:#59491f"><span>🏆 أعلى انطلاقة مسجلة</span><b style="font-size:25px;color:#ffd66b">🚀 ${pct(g.rise_pct)}</b></div>`:g?.missing?`<div class="mini amber" style="margin-top:10px"><span>وش باقي؟</span><b>${g.missing}</b></div>`:''}<div class="grid"><div class="mini"><span>LIVE</span><b class="live">${money(l?.live_price??s.current_price)}</b></div><div class="mini"><span>Available</span><b>${fmt(s.available)}</b></div><div class="mini"><span>CTB</span><b>${pct(s.ctb)}</b></div><div class="mini"><span>Rebate</span><b>${pct(s.rebate_rate)}</b></div><div class="mini"><span>عن القاع</span><b>${pct(s.distance_from_low_pct)}</b></div><div class="mini"><span>الثبات</span><b>${fmt(s.stability_sessions)}/4</b></div><div class="mini"><span>النصف</span><b>${money(s.half_level)} ${s.half_level_reached?'✓':''}</b></div><div class="mini"><span>أعلى 4H</span><b>${pct(s.four_hour_highest_rise_pct)}</b></div></div><h3>Borrow History</h3>${h.map(z=>`<div class="mini" style="margin:5px 0">${new Date(z.timestamp+'Z').toLocaleString('ar-SA')} · ${fmt(z.available)} · ${pct(z.ctb)} · ${pct(z.rebate_rate)}</div>`).join('')}`}catch(e){detail.innerHTML='تعذر التحميل'}}function closeD(){drawer.classList.remove('open')}async function borrow(){bb.disabled=true;bb.textContent='جاري تحديث Borrow...';await fetch('/api/sync/borrow/all');poll()}async function poll(){let s=await fetch('/api/sync/borrow/status').then(r=>r.json());bb.textContent=s.running?`Borrow ${s.processed}/${s.total}`:'تحديث Borrow';if(s.running)setTimeout(poll,1500);else{bb.disabled=false;load()}}load();setInterval(load,60000);
</script></body></html>'''
@app.get('/',response_class=HTMLResponse)
def dashboard(): return HTMLResponse(HTML)
